    for c in customers:
        demand_map[c["id"]] = c["demand"]

    def node_xy(nid):
        if nid == depot_id:
            return depot.get("x", 0.0), depot.get("y", 0.0)
        for c in customers:
            if c["id"] == nid:
                return (0.0 if c["x"] is None else c["x"], 0.0 if c["y"] is None else c["y"])
        return 0.0, 0.0

    def dist(a, b):
        if dist_dict is not None:
            if (a, b) in dist_dict:
                return dist_dict[(a, b)]
            if (b, a) in dist_dict:
                return dist_dict[(b, a)]
        if dist_src is not None and not isinstance(dist_src, dict):
            ia = id_to_index.get(a, None)
            ib = id_to_index.get(b, None)
            if ia is not None and ib is not None:
                return dist_src[ia][ib]
        ax, ay = node_xy(a)
        bx, by = node_xy(b)
        dx = ax - bx
        dy = ay - by
        return (dx * dx + dy * dy) ** 0.5

    coords_available = depot.get("x", None) is not None and depot.get("y", None) is not None
    for c in customers:
        if c["x"] is None or c["y"] is None:
            coords_available = False
            break

    def pseudo_angle(c):
        x = c["x"] - depot.get("x", 0.0)
        y = c["y"] - depot.get("y", 0.0)
        if x >= 0 and y >= 0:
            q = 0
        elif x < 0 <= y:
            q = 1
        elif x <= 0 and y < 0:
            q = 2
        else:
            q = 3
        r = (x * x + y * y) ** 0.5
        return q * 10.0 + (y / (abs(x) + abs(y) + 1e-12)) + r * 1e-9

    if coords_available:
        ordered = sorted(customers, key=lambda c: (pseudo_angle(c), dist(depot_id, c["id"]), c["id"]))
    else:
        ordered = sorted(customers, key=lambda c: (dist(depot_id, c["id"]), -demand_map.get(c["id"], 0), c["id"]))

    routes = []
    route_loads = []

    for c in ordered:
        cid = c["id"]
        dem = demand_map.get(cid, 0)
        if dem > capacity:
            routes.append([cid])
            route_loads.append(dem)
            continue

        best = None
        best_delta = None
        for r_idx, route in enumerate(routes):
            if route_loads[r_idx] + dem > capacity:
                continue
            prev = depot_id
            for pos in range(len(route) + 1):
                nxt = depot_id if pos == len(route) else route[pos]
                delta = dist(prev, cid) + dist(cid, nxt) - dist(prev, nxt)
                cand = (delta, r_idx, pos)
                if best is None or cand < best:
                    best = cand
                    best_delta = delta
                if pos < len(route):
                    prev = route[pos]

        if best is None:
            routes.append([cid])
            route_loads.append(dem)
        else:
            _, r_idx, pos = best
            routes[r_idx].insert(pos, cid)
            route_loads[r_idx] += dem

    def route_cost(route):
        if not route:
            return 0.0
        c = dist(depot_id, route[0])
        for i in range(len(route) - 1):
            c += dist(route[i], route[i + 1])
        c += dist(route[-1], depot_id)
        return c

    improved = True
    while improved:
        improved = False

        for r_idx in range(len(routes)):
            route = routes[r_idx]
            n = len(route)
            if n < 4:
                continue
            better = True
            while better:
                better = False
                best_gain = 0.0
                best_i = -1
                best_j = -1
                for i in range(n - 2):
                    a = depot_id if i == 0 else route[i - 1]
                    b = route[i]
                    for j in range(i + 1, n - 1):
                        c = route[j]
                        d = depot_id if j == n - 1 else route[j + 1]
                        gain = (dist(a, b) + dist(c, d)) - (dist(a, c) + dist(b, d))
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best_i = i
                            best_j = j
                if best_gain > 1e-12:
                    route[best_i:best_j + 1] = reversed(route[best_i:best_j + 1])
                    better = True
                    improved = True

        best_move = None
        best_gain = 0.0
        for i in range(len(routes)):
            ri = routes[i]
            for pos_i in range(len(ri)):
                cid = ri[pos_i]
                dem = demand_map.get(cid, 0)
                ai = depot_id if pos_i == 0 else ri[pos_i - 1]
                bi = depot_id if pos_i == len(ri) - 1 else ri[pos_i + 1]
                remove_cost = dist(ai, cid) + dist(cid, bi) - dist(ai, bi)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    if route_loads[j] + dem > capacity:
                        continue
                    rj = routes[j]
                    prev = depot_id
                    for ins in range(len(rj) + 1):
                        nxt = depot_id if ins == len(rj) else rj[ins]
                        add_cost = dist(prev, cid) + dist(cid, nxt) - dist(prev, nxt)
                        gain = remove_cost - add_cost
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best_move = (i, pos_i, j, ins, cid, dem)
                        if ins < len(rj):
                            prev = rj[ins]
        if best_move is not None:
            i, pos_i, j, ins, cid, dem = best_move
            if i == j:
                continue
            routes[i].pop(pos_i)
            route_loads[i] -= dem
            if i < j and ins > len(routes[j]):
                ins = len(routes[j])
            routes[j].insert(ins, cid)
            route_loads[j] += dem
            improved = True
            continue

        best_swap = None
        best_gain = 0.0
        for i in range(len(routes)):
            ri = routes[i]
            for pi in range(len(ri)):
                ci = ri[pi]
                di = demand_map.get(ci, 0)
                ai = depot_id if pi == 0 else ri[pi - 1]
                bi = depot_id if pi == len(ri) - 1 else ri[pi + 1]
                rem_i = dist(ai, ci) + dist(ci, bi) - dist(ai, bi)
                for j in range(i + 1, len(routes)):
                    rj = routes[j]
                    for pj in range(len(rj)):
                        cj = rj[pj]
                        dj = demand_map.get(cj, 0)
                        if route_loads[i] - di + dj > capacity:
                            continue
                        if route_loads[j] - dj + di > capacity:
                            continue
                        aj = depot_id if pj == 0 else rj[pj - 1]
                        bj = depot_id if pj == len(rj) - 1 else rj[pj + 1]
                        rem_j = dist(aj, cj) + dist(cj, bj) - dist(aj, bj)
                        add_i = dist(ai, cj) + dist(cj, bi) - dist(ai, bi)
                        add_j = dist(aj, ci) + dist(ci, bj) - dist(aj, bj)
                        gain = (rem_i + rem_j) - (add_i + add_j)
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best_swap = (i, pi, j, pj)
        if best_swap is not None:
            i, pi, j, pj = best_swap
            ci = routes[i][pi]
            cj = routes[j][pj]
            di = demand_map.get(ci, 0)
            dj = demand_map.get(cj, 0)
            routes[i][pi] = cj
            routes[j][pj] = ci
            route_loads[i] += dj - di
            route_loads[j] += di - dj
            improved = True

    routes = [r for r in routes if r]
    return routes
